#!/usr/bin/env Rscript
args<-commandArgs(trailingOnly=TRUE);if(length(args)!=1L)stop("Provide project.yaml",call.=FALSE)
all<-commandArgs(trailingOnly=FALSE);self<-normalizePath(sub("^--file=","",grep("^--file=",all,value=TRUE)[[1]]),winslash="/");root<-normalizePath(file.path(dirname(self),"../.."),winslash="/");`%||%`<-function(x,y)if(is.null(x)||!length(x))y else x
source(file.path(root,"app/shiny/R/project_discovery.R"));source(file.path(root,"app/shiny/R/fitness_result_state.R"));project<-read_project_summary(args[[1]],root);result<-choose_latest_fitness_result(discover_fitness_results(project));data<-fitness_result_data(result);call<-fitness_call_column(data);one<-as.character(data[[call]][[1]]);zero<-fitness_download_table(data,"not_present");filtered<-fitness_download_table(data,one);safe<-fitness_download_table(data,NULL,c("feature_id","absent_optional"));tmp<-tempfile(fileext=".csv");write.csv(zero,tmp,row.names=FALSE);header<-readLines(tmp,n=1)
stopifnot(nrow(data)>0L,nrow(zero)==0L,nrow(filtered)>0L,ncol(zero)==ncol(data),nzchar(header),identical(names(safe),intersect(c("feature_id","absent_optional"),names(data))),file.exists(result$table),file.exists(result$comparison_summary),!any(one%in%names(filtered)));cat("PASS\n")
